import{_ as t,a,o as i,a6 as r}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"EU Right of Withdrawal","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/eu-withdrawal/index.md","filePath":"api/graphql-api/shop/eu-withdrawal/index.md","lastUpdated":1787290888000}'),d={name:"api/graphql-api/shop/eu-withdrawal/index.md"};function o(n,e,h,s,l,c){return i(),a("div",null,e[0]||(e[0]=[r('<h1 id="eu-right-of-withdrawal" tabindex="-1">EU Right of Withdrawal <a class="header-anchor" href="#eu-right-of-withdrawal" aria-label="Permalink to &quot;EU Right of Withdrawal&quot;">​</a></h1><p>The EU right-of-withdrawal endpoints let a shopper formally declare that they are exercising their statutory right to withdraw from a purchase (the EU &quot;cooling-off&quot; right). Filing a declaration records the withdrawal against an order and triggers a durable-medium confirmation email back to the shopper — the legally required acknowledgement that the store received their notice.</p><p>Both <strong>authenticated customers</strong> (filing against one of their own orders) and <strong>guests</strong> (proving ownership with an order increment id + email) can file a declaration.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The list, view and authenticated-file operations require an authenticated <strong>customer</strong> — provide the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page for how to obtain and send them.</p><p>The <strong>guest</strong> file operation requires only the storefront key — no customer token. Ownership of the order is proved by supplying the matching order increment id and email.</p><h2 id="withdrawal-must-be-switched-on-first" tabindex="-1">Withdrawal must be switched on first <a class="header-anchor" href="#withdrawal-must-be-switched-on-first" aria-label="Permalink to &quot;Withdrawal must be switched on first&quot;">​</a></h2><p>The feature ships <strong>disabled</strong>. It is turned on per channel in Configuration → Sales → EU Right of Withdrawal, and the setting defaults to off, so a fresh store rejects every filing attempt until an admin enables it.</p><p>Two things make this easy to misdiagnose:</p><ul><li><strong>The error does not mention the setting.</strong> A filing attempt against a disabled channel fails with <em>&quot;The order could not be found or is not eligible for withdrawal.&quot;</em> — the same message an unknown or mismatched order produces. A developer sees &quot;order not found&quot; and goes looking for a wrong order id or email, when the real cause is the configuration flag.</li><li><strong>The check follows the order&#39;s own channel.</strong> Enabling withdrawal on one channel does not enable it for orders placed on another. The gate reads the channel the order belongs to, not the channel the request is made against.</li></ul><p>Only the two filing mutations are gated. Listing and viewing declarations keep working even after the feature is switched off, so declarations filed while it was enabled remain readable.</p><h2 id="filing-is-idempotent" tabindex="-1">Filing is idempotent <a class="header-anchor" href="#filing-is-idempotent" aria-label="Permalink to &quot;Filing is idempotent&quot;">​</a></h2><p>Filing a withdrawal is <strong>idempotent per order</strong>. If a declaration already exists for the given order, a second <code>createEuWithdrawal</code> / <code>createGuestEuWithdrawal</code> call returns the existing declaration unchanged instead of creating a duplicate or raising an error. A confirmation email is sent when the declaration is first created.</p><h2 id="confirmation-on-a-durable-medium" tabindex="-1">Confirmation on a durable medium <a class="header-anchor" href="#confirmation-on-a-durable-medium" aria-label="Permalink to &quot;Confirmation on a durable medium&quot;">​</a></h2><p>When a declaration is first recorded, the store sends a confirmation email to the shopper — the durable-medium acknowledgement the withdrawal right requires. The <code>confirmationSentAt</code> timestamp reflects when that email was dispatched.</p><h2 id="guest-vs-authenticated" tabindex="-1">Guest vs authenticated <a class="header-anchor" href="#guest-vs-authenticated" aria-label="Permalink to &quot;Guest vs authenticated&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flow</th><th>Who</th><th>How ownership is proved</th><th>Fields returned</th></tr></thead><tbody><tr><td>Authenticated</td><td>Logged-in customer</td><td>The order belongs to the authenticated customer</td><td>Full set (includes decline / refund fields)</td></tr><tr><td>Guest</td><td>Anyone with the order details</td><td>Order increment id <strong>+</strong> email must match a guest order</td><td>Reduced set (no decline / refund fields)</td></tr></tbody></table><h2 id="declaration-lifecycle" tabindex="-1">Declaration lifecycle <a class="header-anchor" href="#declaration-lifecycle" aria-label="Permalink to &quot;Declaration lifecycle&quot;">​</a></h2><p>A withdrawal declaration moves through these statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>received</code></td><td>The declaration was received and acknowledged.</td></tr><tr><td><code>declined</code></td><td>The store reviewed and declined the withdrawal.</td></tr><tr><td><code>refunded</code></td><td>The withdrawal was accepted and the order refunded.</td></tr></tbody></table><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List own declarations</td><td><a href="/api/graphql-api/shop/eu-withdrawal/queries/list-eu-withdrawals.html"><code>euWithdrawals</code></a></td><td>Paginated list of the authenticated customer&#39;s own declarations.</td></tr><tr><td>View one declaration</td><td><a href="/api/graphql-api/shop/eu-withdrawal/queries/view-eu-withdrawal.html"><code>euWithdrawal</code></a></td><td>A single declaration the customer owns.</td></tr><tr><td>File (authenticated)</td><td><a href="/api/graphql-api/shop/eu-withdrawal/mutations/create-eu-withdrawal.html"><code>createEuWithdrawal</code></a></td><td>File a declaration against one of the customer&#39;s own orders.</td></tr><tr><td>File (guest)</td><td><a href="/api/graphql-api/shop/eu-withdrawal/mutations/create-guest-eu-withdrawal.html"><code>createGuestEuWithdrawal</code></a></td><td>File a declaration for a guest order using order id + email.</td></tr></tbody></table>',22)]))}const g=t(d,[["render",o]]);export{p as __pageData,g as default};
